#!/usr/bin/env node
// jero-pi docs manifest gate. The reference doc's command/tool/skill counts
// have drifted from the code more than once (CHANGELOG records several count
// corrections). This script derives the three surfaces from the actual
// registration points — the single source of truth — and pins them into
// docs/jero-reference.md as a generated block:
//
//   <!-- jero:manifest:begin (generated by scripts/check-docs-manifest.mjs) -->
//   ...
//   <!-- jero:manifest:end -->
//
// It also verifies the counts embedded in the doc headings
// ("## 命令（N 个斜杠命令）" / "## 技能（N 个目录…）") when present.
//
// Extraction rules (keep in sync with the code or the gate fails loudly):
//   - commands: every `register*Command("literal")` in extensions/*.ts,
//     including the banner helper registerers; `registerCommand(CONST)` is
//     resolved via `const CONST = "..."` in extensions/ or lib/;
//     `registerCommand(`template`)` must be listed in templateExpansions below.
//   - tools: `name: "..."` literals in extensions/*.ts filtered to the
//     jero_review / mem_* / session_worktree_register families, plus
//     `tool("name"` calls in extensions/jero-agents.ts prefixed with the
//     TOOL_PREFIX declared in lib/jero-agents-helpers.ts.
//   - skills: every skills/*/SKILL.md directory except _shared.
//
// Modes: default checks and exits 1 on drift; `--write` regenerates the block
// and the heading counts in place.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(fileURLToPath(new URL("..", import.meta.url)));
const DOC_PATH = join(root, "docs", "jero-reference.md");
const BEGIN_MARKER = "<!-- jero:manifest:begin (generated by scripts/check-docs-manifest.mjs) -->";
const END_MARKER = "<!-- jero:manifest:end -->";

// registerCommand(`jero:install-${owner}`) loops over these owners
// (extensions/jero-ai.ts). A new template literal registration must be added
// here explicitly — silent guessing is exactly what this gate exists to stop.
const templateExpansions = {
	"jero:install-${owner}": ["delegation", "review", "sdd"].map((owner) => `jero:install-${owner}`),
};

const extensionFiles = () =>
	readdirSync(join(root, "extensions"), { withFileTypes: true })
		.filter((entry) => entry.isFile() && entry.name.endsWith(".ts"))
		.map((entry) => join(root, "extensions", entry.name));

const libFiles = () =>
	readdirSync(join(root, "lib"), { withFileTypes: true })
		.filter((entry) => entry.isFile() && entry.name.endsWith(".ts"))
		.map((entry) => join(root, "lib", entry.name));

function collectCommands() {
	const sources = extensionFiles().map((path) => ({ path, text: readFileSync(path, "utf8") }));
	const definitions = new Map();
	for (const { text } of [...sources, ...libFiles().map((path) => ({ path, text: readFileSync(path, "utf8") }))]) {
		for (const match of text.matchAll(/\bconst\s+([A-Z][A-Z0-9_]+)\s*=\s*["']([^"']+)["']/g)) {
			definitions.set(match[1], match[2]);
		}
	}
	const commands = new Set();
	const problems = [];
	for (const { path, text } of sources) {
		const relativePath = relative(root, path);
		for (const match of text.matchAll(/\bregister\w*Command\(\s*(["'])([^"']+)\1/g)) {
			commands.add(match[2]);
		}
		for (const match of text.matchAll(/\bregister\w*Command\(\s*`([^`]+)`\s*,/g)) {
			const expansion = templateExpansions[match[1]];
			if (!expansion) {
				problems.push(`${relativePath}: unknown template literal registration \`${match[1]}\` — add it to templateExpansions`);
				continue;
			}
			for (const name of expansion) commands.add(name);
		}
		// 只有全大写常量名需要解析；helper 内部的小写形参（如 name）由
		// 上面的字面量规则在调用点捕获，这里必须跳过。
		for (const match of text.matchAll(/\bregister\w*Command\(\s*([A-Z][A-Z0-9_]+)\s*,/g)) {
			const resolved = definitions.get(match[1]);
			if (!resolved) {
				problems.push(`${relativePath}: cannot resolve command constant ${match[1]}`);
				continue;
			}
			commands.add(resolved);
		}
	}
	return { commands: [...commands].sort(), problems };
}

function collectTools() {
	const tools = new Set();
	for (const path of extensionFiles()) {
		const text = readFileSync(path, "utf8");
		for (const match of text.matchAll(/\bname:\s*["']((?:jero_|mem_|session_worktree_register)[a-z_]*)["']/g)) {
			tools.add(match[1]);
		}
	}
	const agentsPath = join(root, "extensions", "jero-agents.ts");
	const agentsText = readFileSync(agentsPath, "utf8");
	const prefixMatch = /\bexport\s+const\s+TOOL_PREFIX\s*=\s*["']([^"']+)["']/.exec(
		readFileSync(join(root, "lib", "jero-agents-helpers.ts"), "utf8"),
	);
	if (!prefixMatch) throw new Error("TOOL_PREFIX declaration not found in lib/jero-agents-helpers.ts");
	for (const match of agentsText.matchAll(/\btool\(\s*["']([a-z_]+)["']/g)) {
		tools.add(`${prefixMatch[1]}${match[1]}`);
	}
	return [...tools].sort();
}

function collectSkills() {
	return readdirSync(join(root, "skills"), { withFileTypes: true })
		.filter((entry) => entry.isDirectory() && entry.name !== "_shared")
		.map((entry) => entry.name)
		.sort();
}

function renderManifestBlock(commands, tools, skills) {
	const lines = [
		BEGIN_MARKER,
		`斜杠命令（${commands.length}）：${commands.map((name) => "`/" + name + "`").join(" ")}`,
		`工具（${tools.length}）：${tools.map((name) => "`" + name + "`").join(" ")}`,
		`技能（${skills.length}）：${skills.map((name) => "`" + name + "`").join(" ")}`,
		END_MARKER,
	];
	return lines.join("\n");
}

function currentBlock(doc) {
	const begin = doc.indexOf(BEGIN_MARKER);
	const end = doc.indexOf(END_MARKER);
	if (begin === -1 && end === -1) return undefined;
	if (begin === -1 || end === -1 || end < begin) throw new Error("docs/jero-reference.md has unmatched jero:manifest markers");
	return doc.slice(begin, end + END_MARKER.length);
}

function headingCounts(doc) {
	const commandMatch = /##\s*命令（(\d+)\s*个斜杠命令）/.exec(doc);
	const skillMatch = /##\s*技能（(\d+)\s*个目录/.exec(doc);
	return { command: commandMatch?.[1], skill: skillMatch?.[1] };
}

// 派生 + 校验核心。导出给 tests/docs-manifest.test.ts 直接调用（无子进程），
// CLI 入口只负责退出码与 --write。
export function checkDocsManifest() {
	const { commands, problems } = collectCommands();
	if (problems.length > 0) return { ok: false, problems, failures: [] };
	const tools = collectTools();
	const skills = collectSkills();
	const block = renderManifestBlock(commands, tools, skills);
	const doc = readFileSync(DOC_PATH, "utf8");
	const existing = currentBlock(doc);
	const failures = [];
	if (existing === undefined) failures.push("docs/jero-reference.md is missing the generated jero:manifest block (run with --write)");
	else if (existing !== block) failures.push("the generated jero:manifest block drifted from the registration points");

	const counts = headingCounts(doc);
	if (counts.command !== undefined && counts.command !== String(commands.length)) {
		failures.push(`heading says ${counts.command} commands, code registers ${commands.length}`);
	}
	if (counts.skill !== undefined && counts.skill !== String(skills.length)) {
		failures.push(`heading says ${counts.skill} skills, disk has ${skills.length}`);
	}
	return { ok: failures.length === 0, problems, failures, counts: { commands: commands.length, tools: tools.length, skills: skills.length }, block, doc, existing };
}

function main() {
	const write = process.argv.includes("--write");
	// 判定体只在 checkDocsManifest 里维护一份；CLI 入口只负责 --write
	// 与退出码（此前这里的整段复制曾与导出函数漂移）。
	const result = checkDocsManifest();
	if (result.problems.length > 0) {
		console.error("jero-pi docs manifest extraction failed:");
		for (const problem of result.problems) console.error(`- ${problem}`);
		process.exit(1);
	}
	const { block, doc, existing } = result;
	const { commands: commandCount, tools: toolCount, skills: skillCount } = result.counts;

	if (write) {
		let updated = doc;
		if (existing !== undefined) updated = updated.replace(existing, block);
		else updated = updated.replace("## 测试与打包门", `${block}\n\n## 测试与打包门`);
		updated = updated.replace(/(##\s*命令（)\d+(\s*个斜杠命令）)/, `$1${commandCount}$2`);
		updated = updated.replace(/(##\s*技能（)\d+(\s*个目录)/, `$1${skillCount}$2`);
		writeFileSync(DOC_PATH, updated, "utf8");
		console.log(`jero-pi docs manifest written: ${commandCount} commands, ${toolCount} tools, ${skillCount} skills.`);
		return;
	}

	if (result.failures.length > 0) {
		console.error("jero-pi docs manifest drift detected:");
		for (const failure of result.failures) console.error(`- ${failure}`);
		console.error("\nRegenerate with: node scripts/check-docs-manifest.mjs --write");
		process.exit(1);
	}
	console.log(`jero-pi docs manifest in sync (${commandCount} commands, ${toolCount} tools, ${skillCount} skills).`);
}

const isMainModule = process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMainModule) {
	main();
}
